"""Render deterministic CLI and environment reference documents."""

from __future__ import annotations

import argparse
import ast
import os
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

from agent.env_reference import ENV_VARS

REPO_ROOT = Path(__file__).resolve().parents[1]
MAIN_PATH = REPO_ROOT / "agent" / "__main__.py"
GENERATED_CLI_HEADER = (
    "<!-- Generated by `python scripts/gen_reference_docs.py`; do not edit by hand. -->"
)
GENERATED_ENV_HEADER = (
    "<!-- Generated by `python scripts/gen_reference_docs.py`; do not edit by hand. -->"
)
CATEGORY_ORDER = (
    "llm",
    "mumei",
    "guards",
    "features",
    "lean",
    "mcp",
    "observability",
    "debug",
    "ci",
)
CATEGORY_TITLES = {
    "llm": "LLM provider",
    "mumei": "Mumei integration",
    "guards": "Guards",
    "features": "Features",
    "lean": "Lean",
    "mcp": "MCP",
    "observability": "Observability",
    "debug": "Debugging",
    "ci": "CI",
}


class _ParserCaptured(Exception):
    def __init__(self, parser: argparse.ArgumentParser):
        super().__init__("argparse parser captured")
        self.parser = parser


def markdown_cell(value: object | None) -> str:
    if value is None:
        return "—"
    collapsed = " ".join(str(value).split())
    if not collapsed:
        return "—"
    return collapsed.replace("|", r"\|")


def discover_subcommands(path: Path = MAIN_PATH) -> list[str]:
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    found: list[str] = []

    class CommandVisitor(ast.NodeVisitor):
        def visit_Compare(self, node: ast.Compare) -> None:
            operands = [node.left, *node.comparators]
            for left, right in zip(operands, operands[1:]):
                if (
                    isinstance(left, ast.Name)
                    and left.id == "command"
                    and isinstance(right, ast.Constant)
                    and isinstance(right.value, str)
                    and right.value not in found
                ):
                    found.append(right.value)
                elif (
                    isinstance(right, ast.Name)
                    and right.id == "command"
                    and isinstance(left, ast.Constant)
                    and isinstance(left.value, str)
                    and left.value not in found
                ):
                    found.append(left.value)
            self.generic_visit(node)

    CommandVisitor().visit(tree)
    return found


def capture_parser(main_fn: Callable[[], object], argv: list[str]) -> argparse.ArgumentParser | None:
    original_parse_args = argparse.ArgumentParser.parse_args
    original_parse_known_args = argparse.ArgumentParser.parse_known_args
    original_argv = sys.argv

    def capture(self: argparse.ArgumentParser, *args: object, **kwargs: object) -> object:
        raise _ParserCaptured(self)

    argparse.ArgumentParser.parse_args = capture
    argparse.ArgumentParser.parse_known_args = capture
    sys.argv = list(argv)
    try:
        try:
            main_fn()
        except _ParserCaptured as captured:
            return captured.parser
        return None
    finally:
        argparse.ArgumentParser.parse_args = original_parse_args
        argparse.ArgumentParser.parse_known_args = original_parse_known_args
        sys.argv = original_argv


def _parser_for_command(command: str) -> argparse.ArgumentParser:
    if command == "mcp-server":
        return argparse.ArgumentParser(
            prog="python -m agent mcp-server",
            description="Expose agent tools over the MCP stdio transport; extra arguments are ignored.",
        )
    from agent import __main__ as agent_main

    parser = capture_parser(agent_main.main, ["agent", command])
    if parser is None:
        raise RuntimeError(f"command {command!r} returned without constructing an argparse parser")
    return parser


def _visible_actions(parser: argparse.ArgumentParser, positional: bool) -> list[argparse.Action]:
    actions = []
    for action in parser._actions:
        is_positional = not action.option_strings
        if is_positional != positional:
            continue
        if action.help == argparse.SUPPRESS or isinstance(action, argparse._HelpAction):
            continue
        if any(option in {"-h", "--help"} for option in action.option_strings):
            continue
        actions.append(action)
    return actions


def _value_label(action: argparse.Action) -> str:
    if action.choices is not None:
        choices = action.choices
        if isinstance(choices, (set, frozenset)):
            choices = sorted(choices, key=str)
        return "{" + ", ".join(str(choice) for choice in choices) + "}"
    if action.nargs == 0:
        return "—"
    metavar = action.metavar
    if isinstance(metavar, tuple):
        return " ".join(f"<{part}>" for part in metavar)
    value = str(metavar or action.dest.upper())
    label = f"<{value}>"
    if action.nargs == argparse.OPTIONAL:
        return f"[{label}]"
    if action.nargs in {argparse.ZERO_OR_MORE, argparse.ONE_OR_MORE}:
        repeat = f"{label} ..."
        return f"[{repeat}]" if action.nargs == argparse.ZERO_OR_MORE else repeat
    return label


def _default_label(action: argparse.Action) -> str:
    default = action.default
    if default is None or default == argparse.SUPPRESS:
        return "—"
    if isinstance(action, argparse._StoreTrueAction) and default is False:
        return "—"
    return str(default)


def _help_text(parser: argparse.ArgumentParser, action: argparse.Action) -> str:
    if not action.help:
        return "—"
    return parser._get_formatter()._expand_help(action)


@dataclass(frozen=True)
class CommandReference:
    name: str
    description: str
    parser: argparse.ArgumentParser

    @property
    def options(self) -> list[argparse.Action]:
        return _visible_actions(self.parser, positional=False)


def capture_command_references() -> list[CommandReference]:
    references = []
    with _neutralized_environment():
        for command in discover_subcommands():
            parser = _parser_for_command(command)
            references.append(
                CommandReference(
                    name=command,
                    description=parser.description or "",
                    parser=parser,
                )
            )
    return references


def _neutralized_environment():
    from contextlib import contextmanager
    from unittest.mock import patch

    @contextmanager
    def context():
        import dotenv

        config_module = sys.modules.get("agent.config")
        old_config_loader = getattr(config_module, "load_dotenv", None) if config_module else None
        original_dotenv_loader = dotenv.load_dotenv
        registry_names = {entry.name for entry in ENV_VARS}
        removed = {
            name: os.environ.pop(name)
            for name in tuple(os.environ)
            if name in registry_names
        }
        try:
            with patch.object(dotenv, "load_dotenv", lambda *args, **kwargs: False):
                if config_module is not None:
                    config_module.load_dotenv = lambda *args, **kwargs: False
                yield
        finally:
            config_module = sys.modules.get("agent.config")
            if config_module is not None:
                config_module.load_dotenv = (
                    old_config_loader if old_config_loader is not None else original_dotenv_loader
                )
            os.environ.update(removed)

    return context()


def render_cli_reference() -> str:
    references = capture_command_references()
    lines = [
        "---",
        "layout: default",
        'title: "CLI Option Reference — Mumei Agent"',
        'description: "Generated reference for mumei-agent commands and options."',
        "---",
        "",
        GENERATED_CLI_HEADER,
        "",
        "This reference is generated from the command dispatch and argparse definitions.",
        "A bare `python -m agent <file>` invocation uses `heal` mode. The `mumei-heal`,",
        "`mumei-extract-spec`, and `mumei-agent-mcp` console scripts map to `heal`,",
        "`extract-spec`, and `mcp-server`, respectively.",
        "",
        "| Subcommand | Option count | Description |",
        "|---|---:|---|",
    ]
    for reference in references:
        lines.append(
            f"| `{markdown_cell(reference.name)}` | {len(reference.options)} | "
            f"{markdown_cell(reference.description)} |"
        )
    for reference in references:
        lines.extend(["", f"## `mumei-agent {reference.name}`", ""])
        if reference.description:
            lines.extend([markdown_cell(reference.description), ""])
        for group in reference.parser._mutually_exclusive_groups:
            if not group.required:
                continue
            options = []
            for action in group._group_actions:
                if not action.option_strings:
                    continue
                option = next(
                    (item for item in action.option_strings if item.startswith("--")),
                    action.option_strings[0],
                )
                options.append(f"`{markdown_cell(option)}`")
            if options:
                lines.extend([f"Exactly one of {', '.join(options)} is required.", ""])
        positionals = _visible_actions(reference.parser, positional=True)
        if positionals:
            lines.extend(
                [
                    "### Positional arguments",
                    "",
                    "| Argument | Required | Value | Description |",
                    "|---|---|---|---|",
                ]
            )
            for action in positionals:
                required = action.nargs not in {argparse.OPTIONAL, argparse.ZERO_OR_MORE}
                lines.append(
                    f"| `{markdown_cell(action.dest)}` | {'yes' if required else 'no'} | "
                    f"{markdown_cell(_value_label(action))} | "
                    f"{markdown_cell(_help_text(reference.parser, action))} |"
                )
            lines.append("")
        options = reference.options
        if options:
            lines.extend(
                [
                    "### Options",
                    "",
                    "| Option | Value | Required | Default | Description |",
                    "|---|---|---|---|---|",
                ]
            )
            for action in options:
                option = ", ".join(action.option_strings)
                lines.append(
                    f"| `{markdown_cell(option)}` | {markdown_cell(_value_label(action))} | "
                    f"{'yes' if action.required else 'no'} | "
                    f"{markdown_cell(_default_label(action))} | "
                    f"{markdown_cell(_help_text(reference.parser, action))} |"
                )
            lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def _toggle_summary() -> tuple[str, str]:
    toggles = [entry for entry in ENV_VARS if entry.name.startswith("ENABLE_")]
    enabled = [entry.name for entry in toggles if entry.default.lower() == "true"]
    opt_in = [entry.name for entry in toggles if entry.default.lower() != "true"]
    return (
        ", ".join(f"`{name}`" for name in enabled) or "none",
        ", ".join(f"`{name}`" for name in opt_in) or "none",
    )


def render_env_reference() -> str:
    enabled_by_default, opt_in = _toggle_summary()
    lines = [
        "---",
        "layout: default",
        'title: "Environment Variable Reference — Mumei Agent"',
        'description: "Generated reference for mumei-agent environment variables and defaults."',
        "---",
        "",
        GENERATED_ENV_HEADER,
        "",
        f"**`ENABLE_*` toggles on by default:** {enabled_by_default}.",
        "",
        f"**Opt-in `ENABLE_*` toggles:** {opt_in}.",
        "",
        "Unset optional values are shown as `unset`; toggle defaults are `on` or `off`.",
    ]
    for category in CATEGORY_ORDER:
        entries = [entry for entry in ENV_VARS if entry.category == category]
        if not entries:
            continue
        lines.extend(
            [
                "",
                f"## {CATEGORY_TITLES[category]}",
                "",
                "| Variable | Kind | Default | Description |",
                "|---|---|---|---|",
            ]
        )
        for entry in entries:
            default = entry.default
            if entry.kind == "toggle":
                default = "on" if default.lower() == "true" else "off"
            elif not default:
                default = "unset"
            lines.append(
                f"| `{markdown_cell(entry.name)}` | {entry.kind} | "
                f"{markdown_cell(default)} | {markdown_cell(entry.description)} |"
            )
    return "\n".join(lines).rstrip() + "\n"


def render_references() -> dict[str, str]:
    with _neutralized_environment():
        return {
            "CLI_REFERENCE.md": render_cli_reference(),
            "ENV_REFERENCE.md": render_env_reference(),
        }


def sync_reference_docs(output_dir: Path, check: bool = False) -> list[str]:
    rendered = render_references()
    mismatches = []
    if check:
        for name, content in rendered.items():
            path = output_dir / name
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                mismatches.append(name)
        return mismatches
    output_dir.mkdir(parents=True, exist_ok=True)
    for name, content in rendered.items():
        (output_dir / name).write_text(content, encoding="utf-8")
    return mismatches
